"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

/*
 * Playdesk Slider: a recessed groove, a blue gradient range matching the
 * primary Button, and a white cap thumb.
 */

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track data-slot="slider-track" className="relative h-1.5 w-full grow overflow-hidden rounded-full bg-secondary [box-shadow:var(--shadow-track-inset)]">
            <SliderPrimitive.Indicator data-slot="slider-range" className="absolute h-full [background-image:var(--fill-primary)]" />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "block size-5 rounded-full bg-card",
                "[box-shadow:0_0.0625rem_0.1875rem_oklch(0_0_0_/_0.25),var(--shadow-rim)]",
                "transition-[box-shadow] duration-fast ease-out",
                "hover:[box-shadow:0_0.125rem_0.375rem_oklch(0_0_0_/_0.28),var(--shadow-rim)]",
                "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/35",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
